// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint256).max - c.getBalance(actor));
        vm.deal(actor, amount);
        uint256 initialContractBalance = address(c).balance;
        uint256 initialUserBalance = c.getBalance(actor);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        uint256 finalUserBalance = c.getBalance(actor);
        uint256 finalContractBalance = address(c).balance;
        assertTrue(finalUserBalance == initialUserBalance + finalContractBalance - initialContractBalance);
    }
}
